/** The shared settings file, in `.claude/` and in `~/.claude/`. */
export const SETTINGS_FILE = "settings.json";

/** The local settings file of a project. Git does not track it. */
export const LOCAL_SETTINGS_FILE = "settings.local.json";

/** The path of the project settings file, from the project root. */
export const PROJECT_SETTINGS = `${CLAUDE_DIR}/${SETTINGS_FILE}`;

/** The path of the local settings file, from the project root. */
export const PROJECT_LOCAL_SETTINGS = `${CLAUDE_DIR}/${LOCAL_SETTINGS_FILE}`;

/** The folder of the hook scripts of a project or of the home folder. Claude Code runs hooks from `settings.json`, not from this folder. */
export const CLAUDE_HOOKS_DIR = `${CLAUDE_DIR}/hooks`;

/** The folder of the handoff files, from the project root, when no MiniSpec change is active. One checkout owns them. */
